    // Should reject because HS256 is a symmetric algorithm (checked before allowedAlgorithms)
    await expect(verifyWithJwks(token, { keys, allowedAlgorithms: ['RS256'] })).rejects.toThrow(
      JwtSymmetricAlgorithmNotAllowed
    )
